final class InboxController {
	public function register():void{add_action('rest_api_init',array($this,'routes'));}
	public function routes():void{
		$read=static fn(WP_REST_Request $r)=>Csrf::authorize($r,'bt_manage_operations',false);$write=static fn(WP_REST_Request $r)=>Csrf::authorize($r,'bt_manage_operations',true);
		register_rest_route(BTOA_NAMESPACE,'/inbox/submissions',array('methods'=>'GET','callback'=>array($this,'list'),'permission_callback'=>$read));
		register_rest_route(BTOA_NAMESPACE,'/inbox/submissions/(?P<id>\d+)',array('methods'=>'GET','callback'=>array($this,'get'),'permission_callback'=>$read));
		register_rest_route(BTOA_NAMESPACE,'/inbox/submissions/(?P<id>\d+)/status',array('methods'=>'POST','callback'=>array($this,'status'),'permission_callback'=>$write));
		register_rest_route(BTOA_NAMESPACE,'/inbox/submissions/(?P<id>\d+)/notes',array('methods'=>'POST','callback'=>array($this,'note'),'permission_callback'=>$write));
		register_rest_route(BTOA_NAMESPACE,'/inbox/submissions/(?P<id>\d+)/reply',array('methods'=>'POST','callback'=>array($this,'reply'),'permission_callback'=>$write));
		register_rest_route(BTOA_NAMESPACE,'/inbox/stats',array('methods'=>'GET','callback'=>array($this,'stats'),'permission_callback'=>$read));
		register_rest_route(BTOA_NAMESPACE,'/newsletter/subscribers',array('methods'=>'GET','callback'=>array($this,'subscribers'),'permission_callback'=>$read));
	}
	public function list(WP_REST_Request $r){if(!$this->available())return $this->unavailable();$per=min(100,max(1,(int)($r->get_param('per_page')?:20)));$page=max(1,(int)$r->get_param('page'));$status=sanitize_key((string)$r->get_param('status'));if(!in_array($status,array('new','read','replied'),true))$status='';$result=\Wpistic_Formistic_Database::query_submissions(array('status'=>$status,'form'=>sanitize_text_field((string)$r->get_param('form_name')),'search'=>sanitize_text_field((string)$r->get_param('search')),'date_from'=>$this->date((string)$r->get_param('from')),'date_to'=>$this->date((string)$r->get_param('to')),'paged'=>$page,'per_page'=>$per));return response(array('items'=>array_map(array($this,'format_submission'),(array)$result['items']),'total'=>(int)$result['total'],'page'=>$page,'perPage'=>$per,'totalPages'=>(int)ceil((int)$result['total']/$per)));}
	public function get(WP_REST_Request $r){if(!$this->available())return $this->unavailable();$id=(int)$r['id'];$row=\Wpistic_Formistic_Database::get_submission($id);if(!$row)return error('bt_ops_submission_not_found',__('Submission not found.','brother-tours-operations-api'),404);$item=$this->format_submission($row);$item['replies']=array_map(static fn($x)=>array('id'=>(int)$x->id,'subject'=>(string)$x->reply_subject,'body'=>(string)$x->reply_body,'sentBy'=>(int)$x->sent_by,'sentAt'=>(string)$x->sent_at),(array)\Wpistic_Formistic_Database::get_replies($id));$item['notes']=array_map(static fn($x)=>array('id'=>(int)$x->id,'body'=>(string)$x->note_body,'tags'=>(string)$x->tags,'createdBy'=>(int)$x->created_by,'author'=>(string)($x->display_name??''),'createdAt'=>(string)$x->created_at),(array)\Wpistic_Formistic_Database::get_notes($id));$item['attachments']=array_map(static fn($x)=>array('id'=>(int)$x->id,'name'=>(string)$x->original_name,'mimeType'=>(string)$x->mime_type,'sizeBytes'=>(int)$x->size_bytes,'source'=>(string)$x->source,'externalUrl'=>'external'===(string)$x->source?esc_url_raw((string)$x->external_url):'','uploadedAt'=>(string)$x->uploaded_at),(array)\Wpistic_Formistic_Database::get_attachments($id));$ai=\Wpistic_Formistic_Database::get_ai_meta($id);$item['aiMeta']=$ai?array('spamScore'=>(int)$ai->spam_score,'tags'=>(string)$ai->ai_tags,'reply'=>(string)$ai->ai_reply,'provider'=>(string)$ai->source_provider,'updatedAt'=>(string)$ai->updated_at):null;if('new'===(string)$row->status){\Wpistic_Formistic_Database::set_status($id,'read');$item['status']='read';}return response($item);}
	public function status(WP_REST_Request $r){if(!$this->available())return $this->unavailable();$id=(int)$r['id'];if(!\Wpistic_Formistic_Database::get_submission($id))return error('bt_ops_submission_not_found',__('Submission not found.','brother-tours-operations-api'),404);$p=$this->params($r);$status=sanitize_key((string)($p['status']??''));if(!in_array($status,array('new','read','replied'),true))return error('bt_ops_submission_status_invalid',__('Invalid submission status.','brother-tours-operations-api'),422);\Wpistic_Formistic_Database::set_status($id,$status);return response(array('id'=>$id,'status'=>$status));}
	public function note(WP_REST_Request $r){if(!$this->available())return $this->unavailable();$id=(int)$r['id'];if(!\Wpistic_Formistic_Database::get_submission($id))return error('bt_ops_submission_not_found',__('Submission not found.','brother-tours-operations-api'),404);$p=$this->params($r);$note=sanitize_textarea_field((string)($p['note']??''));$tags=sanitize_text_field((string)($p['tags']??''));if(trim($note)==='')return error('bt_ops_submission_note_required',__('A note is required.','brother-tours-operations-api'),422);$note_id=\Wpistic_Formistic_Database::insert_note($id,$note,$tags);return response(array('id'=>(int)$note_id,'submissionId'=>$id,'saved'=>(bool)$note_id),201);}
	public function reply(WP_REST_Request $r){if(!$this->available())return $this->unavailable();if(!class_exists('\\Wpistic_Formistic_Capture'))return error('bt_ops_formistic_mail_unavailable',__('Formistic mail service is unavailable.','brother-tours-operations-api'),503);$id=(int)$r['id'];$row=\Wpistic_Formistic_Database::get_submission($id);if(!$row)return error('bt_ops_submission_not_found',__('Submission not found.','brother-tours-operations-api'),404);$p=$this->params($r);$to=sanitize_email((string)$row->sender_email);$subject=sanitize_text_field((string)($p['subject']??''));$html=!empty($p['html']);$body=$html?wp_kses_post((string)($p['body']??'')):sanitize_textarea_field((string)($p['body']??''));if(!is_email($to)||$subject===''||trim($body)==='')return error('bt_ops_reply_invalid',__('A valid recipient, subject, and message are required.','brother-tours-operations-api'),422);$signature=(string)get_option('wpistic_formistic_reply_signature','');$full=$body;if(trim($signature)!=='')$full.=($html?'<br><br>--<br>':"\n\n--\n").($html?nl2br(esc_html($signature)):$signature);$from_name=sanitize_text_field((string)get_option('wpistic_formistic_reply_from_name',get_bloginfo('name')));$from_email=sanitize_email((string)get_option('wpistic_formistic_reply_from_email',get_option('admin_email')));$headers=array();if(is_email($from_email)){$headers[]=sprintf('From: %s <%s>',$from_name,$from_email);$headers[]='Reply-To: '.$from_email;}if($html)$headers[]='Content-Type: text/html; charset=UTF-8';foreach(array('cc'=>'Cc','bcc'=>'Bcc') as $key=>$label)foreach($this->emails((string)($p[$key]??'')) as $address)$headers[]=$label.': '.$address;$sent=\Wpistic_Formistic_Capture::send_internal($to,$subject,$full,$headers);if(!$sent)return error('bt_ops_reply_failed',__('The email could not be sent. Check the site mail configuration.','brother-tours-operations-api'),500);\Wpistic_Formistic_Database::insert_reply($id,$subject,$full);\Wpistic_Formistic_Database::set_status($id,'replied');return response(array('submissionId'=>$id,'sent'=>true,'status'=>'replied'));}
	public function stats(){if(!$this->available())return $this->unavailable();$by=\Wpistic_Formistic_Database::submissions_by_day(30);$subs=class_exists('\\Wpistic_Formistic_Newsletter')?\Wpistic_Formistic_Newsletter::subscriber_counts():array('active'=>0,'unsubscribed'=>0,'total'=>0);return response(array('statusCounts'=>\Wpistic_Formistic_Database::status_counts(),'today'=>(int)\Wpistic_Formistic_Database::today_count(),'last7Days'=>(int)array_sum(array_slice($by,-7,7,true)),'last30Days'=>(int)array_sum($by),'byDay'=>$by,'forms'=>\Wpistic_Formistic_Database::form_names(),'avgReplySeconds'=>(int)\Wpistic_Formistic_Database::avg_reply_time_seconds(),'medianReplySeconds'=>(int)\Wpistic_Formistic_Database::p50_reply_time_seconds(),'repliedRate'=>(float)\Wpistic_Formistic_Database::replied_rate(),'overdue24h'=>(int)\Wpistic_Formistic_Database::overdue_submissions_count(24),'subscribers'=>$subs));}
	public function subscribers(WP_REST_Request $r){if(!class_exists('\\Wpistic_Formistic_Newsletter'))return error('bt_ops_newsletter_unavailable',__('Formistic newsletter module is unavailable.','brother-tours-operations-api'),503);$page=max(1,(int)$r->get_param('page'));$per=min(100,max(1,(int)($r->get_param('per_page')?:25)));$status=sanitize_key((string)$r->get_param('status'));if(!in_array($status,array('active','unsubscribed'),true))$status='';$result=\Wpistic_Formistic_Newsletter::query_subscribers(array('status'=>$status,'search'=>sanitize_text_field((string)$r->get_param('search')),'paged'=>$page,'per_page'=>$per));$items=array_map(static fn($x)=>array('id'=>(int)$x->id,'email'=>(string)$x->email,'source'=>(string)$x->source,'status'=>(string)$x->status,'consentAt'=>(string)$x->consent_at,'unsubscribedAt'=>(string)($x->unsubscribed_at??'')),(array)$result['items']);return response(array('items'=>$items,'total'=>(int)$result['total'],'page'=>$page,'perPage'=>$per,'totalPages'=>(int)ceil((int)$result['total']/$per)));}
	public function format_submission(object $row):array{$fields=json_decode((string)$row->fields,true);return array('id'=>(int)$row->id,'formName'=>(string)$row->form_name,'senderName'=>(string)$row->sender_name,'senderEmail'=>(string)$row->sender_email,'senderPhone'=>(string)$row->sender_phone,'subject'=>(string)$row->subject,'message'=>(string)$row->message,'fields'=>is_array($fields)?$fields:array(),'sourceUrl'=>(string)$row->source_url,'status'=>(string)$row->status,'createdAt'=>(string)$row->created_at);}
	private function available():bool{return class_exists('\\Wpistic_Formistic_Database');}private function unavailable(){return error('bt_ops_formistic_unavailable',__('Formistic is unavailable.','brother-tours-operations-api'),503);}private function params(WP_REST_Request $r):array{$j=$r->get_json_params();return is_array($j)?$j:$r->get_params();}private function date(string $v):string{$v=trim($v);return preg_match('/^\d{4}-\d{2}-\d{2}$/',$v)?$v:'';}private function emails(string $raw):array{$out=array();foreach(explode(',',$raw) as $v){$v=sanitize_email(trim($v));if(is_email($v))$out[]=$v;}return array_values(array_unique($out));}
}
